"""Generate the buildless Finnish guide. Python standard library only."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parent
chapters = []
def chapter(slug, title, intro, path, steps, features, shots=(), note=''):
    chapters.append(dict(slug=slug, title=title, intro=intro, path=path, steps=steps, features=features, shots=shots, note=note))

chapter('aloittaminen', 'Käyttöönotto',
 'GymTracker kulkee mukana suunnittelusta viimeiseen sarjaan. Aloita omasta tavoitteestasi ja tee sovelluksesta sinulle sopiva.',
 'Ensikäynnistys · myöhemmin <strong>⋮ → Asetukset</strong>',
 ['Valitse kieli ja tutustu aloitusohjeisiin.', 'Valitse tavoite, kokemustaso, treenirytmi, treeniympäristö ja välineet. Perustiedot, kuten ikäryhmä ja sukupuoli, ovat vapaaehtoisia.', 'Luo ohjelma tai palauta aiempi GymTracker-varmuuskopio. Tarkista sen jälkeen treenipäivät ja liikkeet.'],
 [('Kolme välilehteä ja yksi päävalikko', '<p><strong>Treeni</strong> näyttää seuraavan treenin ja ohjelmasi. <strong>Kehonhuolto</strong> kokoaa palauttavat ja liikkuvuusharjoitukset. <strong>Historia</strong> näyttää tehdyt harjoitukset ja kehityksen.</p><p>Yläkulman <strong>⋮</strong> avaa sovellusvalikon. Sen sisältö muuttuu näkymän mukaan: treenin aikana mukana ovat myös harjoituksen toiminnot. Asetukset, ohje ja sovelluksen tiedot löytyvät samasta valikosta.</p>'),
  ('Tilaus, kokeilu ja aiemmat käyttöoikeudet', '<p>Avaa tilausnäkymä sovelluksen valikosta. Näet oman käyttöoikeutesi, saatavilla olevat tilaukset ja Google Playn ajantasaiset hinnat. Maksuton kokeilu on tarjolla siihen oikeutetuille; tarkista ehdot ennen vahvistamista.</p><p>Tilauksia hallitaan ja perutaan Google Playssa. <strong>Palauta ostot</strong> tarkistaa aiemman oston oikealla Google-tilillä. Lifetime-oikeus ja aiempien käyttäjien säilyvät oikeudet näkyvät omassa tilausnäkymässä.</p><p>Harjoitushistoria säilyy käyttöoikeuden päätyttyä. Uuden harjoittelun ja lisäominaisuuksien saatavuus riippuu omasta käyttöoikeudestasi. Varmuuskopio palauttaa tietoja, mutta ei korvaa oston palautusta.</p>'),
  ('Kieli ja ensimmäiset käyttövinkit', '<p>Avaa <strong>Asetukset → lippukuvake</strong> ja valitse kieli. Jos sovellus pyytää käynnistämään itsensä uudelleen, tee se vaihdon viimeistelemiseksi.</p><p>Lyhyet käyttövinkit opastavat uusissa toiminnoissa. Treenissä saat opastuksen uudelleen valitsemalla <strong>⋮ → Näytä treenin käyttöopastus</strong>. Valmentajan asetusten valikossa voit palauttaa käyttövinkkejä sekä erillisiä Valmentajan tietoikkunoita.</p>')],
 [('11-asetukset', 'Asetuksista löydät treenaamisen, kellon ja sovelluksen omat valinnat.')])

chapter('ohjelmat', 'Treeniohjelmat',
 'Voit antaa GymTrackerin muodostaa ohjelman tai rakentaa treenipäivät itse. Valmis ohjelma on aina muokattavissa.',
 '<strong>⋮ → Asetukset → Treenaaminen → Luo treeniohjelma</strong>',
 ['Valitse uuden ohjelman lähtökohta ja tavoitteet.', 'Määritä kokemus, treenien määrä ja kesto sekä ympäristö ja käytettävissä olevat välineet.', 'Tarkista esikatselu. Valitse tarjolla oleva tallennustapa ja vahvista vasta, kun kokonaisuus sopii sinulle.'],
 [('Automaattinen ohjelmanluonti ja esikatselu', '<p>Valitse esimerkiksi lihasmassan, voiman tai kunnon ylläpidon tavoite. Sovellus sovittaa ohjelmaa valitsemaasi tasoon, rytmiin ja aikaan. Olemassa olevan ohjelman pohjalta voit säilyttää tutun rungon, hakea tasapainoista uudistusta tai toivoa enemmän vaihtelua.</p><p>Esikatselussa tarkistat päivät, liikkeet ja sarjat ennen tallennusta. <strong>Korvaaminen</strong> vaihtaa tulevan ohjelman; <strong>lisääminen</strong> laajentaa sitä, kun käyttöoikeus sallii. Aiemmat toteutuneet treenit säilyvät historiassa.</p>'),
  ('Viikko-ohjelma vai joustava treenikierto?', '<p><strong>Perinteinen viikko-ohjelma</strong> sopii säännölliseen viikkorytmiin. <strong>Joustava treenikierto</strong> etenee treenipäivästä seuraavaan, vaikka viikon treenipäivät vaihtelisivat.</p><p>Joustavan ohjelman laajuudella valitset kompaktin, normaalin tai monipuolisemman kokonaisuuden. Treeni-välilehti kertoo, mikä harjoitus on seuraavana. Voit avata myös haluamasi muun treenipäivän.</p>'),
  ('Sali, koti, ulkoilu ja välinevalinnat', '<p>Määritä välineet ympäristöittäin. Voit merkitä välineen suosittavaksi, neutraaliksi, vältettäväksi tai kokonaan pois käytöstä tarjolla olevien valintojen mukaan. Valinnat ohjaavat uusia ohjelmia ja sopivia vaihtoliikkeitä.</p><p>Pelkkä välineasetuksen vaihto ei muokkaa kaikkia nykyisen ohjelmasi liikkeitä. Tarkista ohjelma muutoksen jälkeen. Yhden päivän tilapäiseen muutokseen käytä treenin <strong>Treenaa kotona/ulkona</strong> -toimintoa.</p>'),
  ('Omaa lajia tukeva voimaharjoittelu', '<p>Ohjelmanluonnissa voit valita muun lajin tuen. Mukana ovat juoksu, pyöräily, ratsastus, uinti, palloilu, kamppailulajit, mailapelit ja hiihto.</p><p>Valitse, haluatko tukea lajin vaatimuksia, tasapainottaa sen kuormitusta vai yhdistää nämä. GymTracker painottaa sopivia lihasryhmiä ja liikemalleja käytettävissä olevan ajan ja välineiden mukaan. Varsinaiset lajiharjoitukset kirjataan kohdasta <strong>Muut treenit</strong>.</p>'),
  ('Treenipäivän luominen ja muokkaaminen käsin', '<p>Avaa <strong>Asetukset → Treenaaminen → Treeniasetukset → Treenipäivät</strong>. Lisää päivä, nimeä se ja valitse liikkeet. Määritä sarjat, toisto- tai aikaväli ja tarvittaessa painot.</p><p>Avaa olemassa oleva päivä muokataksesi nimeä, liikkeitä tai niiden järjestystä. Voit lisätä ja poistaa liikkeitä, muuttaa tavoitteita sekä poistaa tarpeettoman treenipäivän. Tarkista poistovahvistus ennen hyväksymistä.</p>')],
 [('13-ohjelman-luonti', 'Uusi ohjelma voi lähteä nykyisestä rungosta tai kokonaan alusta.')])

chapter('liikkeet', 'Liikekirjasto',
 'Liikekirjasto yhdistää liikkeiden kuvat, ohjeet ja oletusasetukset. Omilla liikkeillä täydennät ohjelman juuri omalle salillesi.',
 '<strong>Asetukset → Treenaaminen → Treeniasetukset → Liikkeet</strong>',
 ['Hae liikettä nimellä ja rajaa tarvittaessa lihasryhmällä.', 'Avaa liikkeen tiedot tai muokkaus. Tarkista nimi, sarjat, tavoitteet ja painot.', 'Tallenna muutokset. Lisää oma liike, jos sopivaa ei löydy.'],
 [('Kuvat, suoritusohjeet ja lihaskartta', '<p>Treenin liikekortin valikosta avaat <strong>Näytä ohje</strong> -toiminnon. Sisäänrakennetuilla liikkeillä on saatavuuden mukaan kuva ja ohjeet alkuasennosta, suorituksesta ja huomioitavista asioista.</p><p>Pyyhkäise liikekuvaa vasemmalle suurentaaksesi lihaskartan ja oikealle palataksesi kuvaan. Myös pieni esikatselukuva vaihtaa näkymää. Kartta kertoo kohdealueista; se ei mittaa lihaksen kuormitusta kehossasi.</p>'),
  ('Oma liike ja liikkeen oletukset', '<p>Anna omalle liikkeelle selkeä nimi, lihasryhmä ja tyyppi. Määritä oletussarjat, toistoväli, oletuspaino ja painon muutosaskel soveltuvin osin. Voit lisätä oman suoritusohjeen.</p><p>Kirjaston oletukset, ohjelman päiväkohtaiset tavoitteet ja jo aloitettu treeni ovat eri asioita. Tarkista muutoksen kohde tallentaessasi. Sisäänrakennetun liikkeen tunniste on lukittu, jotta sen historia pysyy yhteydessä oikeaan liikkeeseen.</p>'),
  ('Piilottaminen ja liikkeen kehitystiedot', '<p>Poista turha liike käytöstä sen muokkauksessa. Piilotus pitää kirjaston selkeänä ja säilyttää vanhat harjoitusmerkinnät ymmärrettävinä.</p><p>Liikkeen kehitysnäkymässä tarkastelet viimeisimpiä tuloksia ja painollisten liikkeiden arvioitua 1RM-kehitystä. Rajaa tarkastelu viimeisiin 7, 10 tai 15 treeniin tai koko historiaan tarjolla olevan valikon mukaan.</p>')],
 [('15-liikekirjasto', 'Hae liikettä ja avaa sen tiedot kirjastosta.')])

chapter('treeni', 'Treenin kirjaaminen',
 'Treenissä yksi liikekortti pitää tärkeimmät asiat näkyvissä. Voit tehdä liikkeet myös itsellesi sopivassa järjestyksessä.',
 '<strong>Treeni → Aloita treeni</strong> tai avaa ohjelman treenipäivä',
 ['Tarkista liike, sarjat ja tavoite. Avaa tarvittaessa liikkeen ohje.', 'Napauta sarjaa kirjataksesi sen tehdyksi. Syötä paino, jos sovellus pyytää sitä.', 'Tarkista toteutuneet toistot. Siirry seuraavaan liikkeeseen ja lopuksi päätä treeni valikosta.'],
 [('Sarjan kirjaaminen ja toistojen korjaaminen', '<p>Napauta tekemätöntä sarjaa merkitäksesi sen tehdyksi. Sovellus käyttää sarjan tavoitetta lähtökohtana. <strong>Tehdyn sarjan uusi napautus vähentää toistoja</strong> – tarkista luku vastaamaan todellista suoritusta.</p><p>Keho­painoliikkeen kirjaamiseen et tarvitse painoa. Painollisessa liikkeessä ensimmäinen kirjaus voi pyytää painon. Kirjaa käytetty kuorma johdonmukaisesti; avustetussa liikkeessä numero voi tarkoittaa avustusta.</p>'),
  ('Painon muuttaminen numeronäppäimistöllä', '<p><strong>Pidä sarjaa painettuna</strong> avataksesi painon muokkauksen. Napauta painokenttää, syötä arvo sovelluksen numeronäppäimistöllä ja tallenna. Vahvista myös mahdollinen sarjan painodialogi.</p><p>Desimaalierotin löytyy näppäimistöstä. Korjaa virhe poistopainikkeella. Tarkista, mitä sarjoja tai tulevia tavoitteita näkyvä vahvistus koskee.</p>'),
  ('Aikapohjaiset sarjat', '<p>Napauta tekemätöntä aikasarjaa avataksesi ajanoton. <strong>Käynnistä ajanotto erikseen</strong>, kun olet valmis aloittamaan. Pysäytä ja tallenna toteutunut aika näkymän painikkeilla.</p><p>Aikasarjan tavoite on sekunteina, ei toistoina. Kaksipuolisissa kehonhuolto- ja venyttelyliikkeissä puolilla voi olla omat ajastimensa.</p>'),
  ('Liikkeiden selaaminen ja valmistumisen merkit', '<p>Vaihda liikettä pyyhkäisemällä kortteja ylös tai alas, napauttamalla edellisen tai seuraavan liikkeen palkkia tai valitsemalla kuvarivin pienoiskuva.</p><p>Pienoiskuva kertoo tehtyjen sarjojen etenemisestä. Voit palata liikkeeseen myöhemmin. Treenin ei tarvitse edetä listan järjestyksessä.</p>'),
  ('Treenin mittarien vaihtaminen', '<p>Napauta mittaria ja valitse, mitä haluat sen näyttävän. Käytettävissä voivat olla esimerkiksi kulunut aika, syke, keskisyke, aktiiviset kalorit ja askeleet. Muissa treeneissä mukana ovat myös matka, vauhti tai nopeus.</p><p>Valintasi muistetaan tuleviin treeneihin. Mittarivalikoima riippuu harjoituksesta, laitteista ja kertyneestä datasta. Viiva tai puuttuva mittari tarkoittaa, ettei tietoa ole saatavilla.</p>')],
 [('05-sarja-tehty', 'Tehty sarja erottuu värillä. Yläreunassa kulkee lepoajastin.'), ('04-painon-syotto', 'Painon syöttö onnistuu sovelluksen omalla numeronäppäimistöllä.')])

chapter('lammittely', 'Lämmittely ja lepoajastin',
 'Yleislämmittely valmistaa treeniin. Sarjojen välinen lepoajastin auttaa pitämään oman rytmin.',
 '<strong>Asetukset → Treenaaminen → Lämmittely ja lepo</strong> · treenissä kellokuvake',
 ['Ota käyttöön haluamasi yleislämmittely ja liikekohtaiset lämmittelysarjat.', 'Käynnistä ja päätä yleislämmittely sen omasta kortista.', 'Säädä lepoaika kellokuvakkeesta. Tehty sarja käynnistää ajastimen, kun automaattinen lepoajastin on käytössä.'],
 [('Yleislämmittely ja lämmittelysarjat', '<p>Yleislämmittely näkyy harjoituksen ensimmäisenä omana korttina. Sen valmistuminen vie varsinaisiin liikkeisiin. Liikekohtaiset lämmittelysarjat otetaan käyttöön erikseen.</p><p>Lämmittely ja työsarjat erotetaan toisistaan. Yleislämmittelyn kirjaus ei itsessään aiheuta Valmentajan progressio-, kevennys- tai liikkeenvaihtopäätöstä.</p>'),
  ('Lepoaika, pysäytys ja värinä', '<p>Kellokuvakkeesta avautuvat lepoajastimen ja lämmittelyn asetukset. Tarkista haluamasi lepoajan pituus ja automaattinen käynnistys. Käynnissä olevan levon jäljellä oleva aika näkyy treenin yläreunassa.</p><p>Voit päättää levon näkymän ohjaimesta. Värinän valitset lepoasetuksista ja kellon värinät erikseen Wear OS -asetuksista.</p>')])

chapter('muokkaus', 'Treenin muokkaaminen',
 'Laite varattu, vähemmän aikaa tai tänään kevyempi päivä? Muutosten yhteydessä valitset, koskevatko ne tätä treeniä vai myös ohjelmaa.',
 'Liikekortin valikko · koko treenin <strong>⋮</strong>',
 ['Avaa liikkeen valikko vaihtaaksesi liikettä tai sarjatavoitteita.', 'Valitse vahvistuksessa muutoksen laajuus.', 'Tarkista päivitetty treeni ennen seuraavaa sarjaa.'],
 [('Lisää, vaihda tai poista liike', '<p><strong>⋮ → Lisää liike tähän treeniin</strong> avaa liikekirjaston. Liikekohtaisesta valikosta voit vaihtaa tai poistaa liikkeen ja muokata sen tavoitteita.</p><p><strong>Vain tämä treeni</strong> jättää tulevan ohjelman ennalleen. <strong>Päivitä ohjelmaan</strong> tekee muutoksen myös tulevia harjoituksia varten. Poistossa vastaava valinta on <strong>Poista ohjelmasta</strong>. Lue vahvistus ennen hyväksymistä.</p>'),
  ('Lisää tai poista sarjoja ja muuta tavoitteita', '<p>Liikkeen valikosta voit lisätä sarjan tai poistaa viimeisen sarjan sekä muuttaa toisto- tai aikaväliä. Sovellus näyttää mahdollisen valinnan tämän treenin ja ohjelman päivittämisen välillä.</p><p>Aiemmin tehdyt sarjat ovat toteutunutta treenidataa. Tarkista uuden tavoitteen jälkeen jäljellä olevat tekemättömät sarjat.</p>'),
  ('Tilapäinen koti- tai ulkotreeni', '<p>Valitse treenin <strong>⋮ → Treenaa kotona/ulkona</strong>. Merkitse juuri tänään käytettävissä olevat välineet ja tuet, kuten käsipainot, vastuskuminauha, penkki tai leuanvetotanko. Valitse <strong>Luo korvaava treeni</strong>.</p><p>Korvaukset koskevat tätä harjoitusta. Tarkista yhteenveto: kaikille saliliikkeille ei välttämättä löydy sopivaa vaihtoehtoa. Liikkeitä, joissa on jo tehtyjä sarjoja, ei muuteta.</p>'),
  ('Kevennä yksi treeni tai palaa tauolta', '<p>Valitse <strong>⋮ → Tee kevennetty treeni</strong>. Toiminto voi keventää tekemättömien painollisten sarjojen painoja ja vähentää kuormittavien liikkeiden sarjoja. Ohjelma ja pysyvät oletuspainot säilyvät.</p><p>Pitkän harjoitustauon jälkeen sovellus voi tarjota kevennettyä paluuta. Voit valita päivän kevennyksen tai jatkaa tavallisesti.</p>'),
  ('Jatka kesken jäänyttä tai lopeta harjoitus', '<p>Palaa <strong>Treeni</strong>-välilehdelle ja jatka aktiivista harjoitusta. Sovellus ohjaa ratkaisemaan keskeneräisen harjoituksen ennen toisen aloittamista.</p><p>Valitse lopuksi <strong>⋮ → Lopeta treeni</strong>. Jos sarjoja puuttuu, voit jatkaa harjoitusta, tallentaa tehdyn osuuden valitsemalla <strong>Lopeta silti</strong> tai poistaa harjoituksen. Poistaminen hylkää sen merkinnät.</p><p>Yhteenvedosta näet keston, tehdyt sarjat, suoritusasteen ja lihaskuormituksen sekä saatavilla olevat terveystiedot. <strong>Avaa treenin tiedot</strong> näyttää liikkeet ja sarjat.</p>')],
 [('07-yhteenveto', 'Yhteenveto näyttää todellisen toteutuksen myös silloin, kun teit vain osan suunnitelmasta.')])

chapter('muut-treenit', 'Muu liikunta ja GPS',
 'Kävely, juoksu, pyöräily ja muut lajit kuuluvat samaan harjoitusarkeen. Voit tallentaa ajan ja halutessasi GPS-reitin.',
 '<strong>Treeni → Muut treenit</strong>',
 ['Valitse liikuntalaji. Valitse tuetussa lajissa, tallennetaanko reitti GPS:llä.', 'Aloita harjoitus. Salli tarvittavat sijainti- ja muut luvat, jos haluat mittaukset käyttöön.', 'Käytä Tauko- ja Jatka-painikkeita tarvittaessa. Lopeta harjoitus, tarkista yhteenveto ja lisää haluamasi tiedot.'],
 [('Ulkolajit ja sisäkardio', '<p>Valittavana ovat kävely, juoksu ja pyöräily sekä juoksumatto, kuntopyörä, crosstrainer, soutulaite, porraslaite ja muu kardio. Selaa lajilistaa nähdäksesi kaikki vaihtoehdot.</p><p>Sisälajeissa voit tallentaa ajan ja lisätä matkan harjoituksen jälkeen. GPS-reitti on käytettävissä sitä tukevissa ulkolajeissa.</p>'),
  ('GPS-reitti, matka, vauhti ja nopeus', '<p>GPS-seuranta on valittavissa sitä tukevissa lajeissa. Odota sijainnin löytymistä. Tallennuksen aikana näet käytettävissä olevan matkan ja lajille sopivan vauhdin tai nopeuden. Mittaria napauttamalla voit vaihtaa näkyvää tietoa.</p><p>GPS-katkoksen aikana harjoituksen tallennus jatkuu. Kartan katkoviiva tarkoittaa arvioitua suoraa yhteyttä katkoksen yli. Karttapohjan lataus tarvitsee verkkoyhteyden; karttapohjan puuttuminen ei tarkoita tallennetun reitin kadonneen.</p>'),
  ('Tauko, lopetus ja omat tiedot', '<p><strong>Tauko</strong> keskeyttää aktiivisen seurannan ja <strong>Jatka</strong> jatkaa sitä. <strong>Lopeta</strong> tallentaa harjoituksen vahvistuksen jälkeen. <strong>Peru harjoitus</strong> hylkää aloittamattoman tai peruttavan harjoituksen näkymän vahvistuksen mukaisesti.</p><p>Yhteenvedosta voit avata <strong>Muokkaa tietoja</strong> ja korjata tarjolla olevia tietoja, kuten matkaa, kestoa ja muistiinpanoja. Matkan ja muistiinpanojen kyselyn voit valita näytettäväksi harjoituksen lopuksi.</p>'),
  ('Syke, energia ja tiedot historiassa', '<p>Yhteensopiva Wear OS -kello voi tuottaa syke-, askel- ja energiadataa. Mittarit näkyvät vain, kun laite ja annetut luvat tarjoavat ne. Energiankulutus on arvio.</p><p>Valmis harjoitus löytyy Historiasta. Avaa se nähdäksesi keston, matkan, reitin ja saatavilla olevat mittaukset. Myös Health Connectista tuodut harjoitukset erotetaan niiden lähteen perusteella.</p>')],
 [('14-muut-treenit', 'Valitse laji ja päätä, tallennetaanko GPS-reitti.')])

chapter('valmentaja', 'Valmentaja',
 'Valmentaja yhdistää kirjaamaasi harjoittelua, paikallista analyysiä ja tekoälyn arviota. Sinä valitset, kuinka aktiivisesti se osallistuu.',
 '<strong>Asetukset → Treenaaminen → Valmentaja</strong>',
 ['Ota Valmentaja käyttöön. Valitse Ehdota tai Automaattinen.', 'Säädä tarvittaessa progression, kevennysten, liikevaihtojen ja ohjelman hienosäädön toimintaa erikseen.', 'Lue ehdotuksen perustelu ennen hyväksymistä. Tarkista automaattisten muutosten yhteenveto.'],
 [('Ehdota, Automaattinen ja Pois', '<p><strong>Ehdota</strong> jättää muutoksen hyväksymisen sinulle. <strong>Automaattinen</strong> sallii tarkistettujen muutosten tekemisen sovelluksen sääntöjen rajoissa. Toimintokohtaiset valinnat voivat muodostaa <strong>Mukautettu</strong>-tilan.</p><p>Valmentajan pääkytkin pysäyttää toiminnot ja säilyttää omat asetuksesi. Voit kytkeä yksittäisen toiminnon pois sen omista asetuksista. <strong>Hellä, Normaali ja Rohkea</strong> säätävät progression herkkyyttä; valitse omaan harjoitteluusi sopiva taso.</p>'),
  ('Progressio, lisäsarjat ja aikatavoitteet', '<p>Kun vertailukelpoinen harjoitushistoria tukee muutosta, Valmentaja voi ehdottaa painon muuttamista, lisäsarjaa tai aikapohjaisen liikkeen tavoiteajan pidentämistä.</p><p>Tilapäinen variaatio voi yhdistää hieman kevyemmän painon ja lisäsarjan vain tähän harjoitukseen. Avustetussa liikkeessä pienempi avustus voi tarkoittaa vaikeampaa suoritusta. Napauta treenin Valmentaja-kuvaketta nähdäksesi tyypin, perustelun ja toimintopainikkeet.</p>'),
  ('Kevennys ja liikevaihdot', '<p><strong>Kevennyskerta eli deload</strong> voi tilapäisesti pienentää painoa ja sarjamäärää, kun harjoituskokonaisuus puoltaa kevennystä. Liikkeen pysyvät perusasetukset säilyvät.</p><p><strong>Liikevariaatio</strong> vaihtaa liikkeen tarkoitukseen ja käytettävissä oleviin välineisiin sopivaan vaihtoehtoon. Tarkista ehdotus ja sen kohde; tarvittaessa selaa muita vaihtoehtoja tai pidä nykyinen liike.</p><p>Yksittäinen heikompi treeni tai puuttuva tieto ei yksin tarkoita, että ohjelmaa pitäisi muuttaa.</p>'),
  ('Valmentajan palaute ja tekoälyn kokonaisarvio', '<p>Avaa <strong>Treeni-välilehden ⋮ → Valmentajan palaute</strong>. Arviosta näet kokonaiskuvan, tärkeimmät havainnot ja seuraavan painopisteen. Tarkista päivitysaika. Näkymän valikosta voi pyytää uuden arvion, kun toiminto on saatavilla.</p><p>Tekoälyarvio käyttää palvelinyhteyttä. Mukana voi olla harjoitus- ja ohjelmayhteenvetoja, viikkokyselyn vastauksia sekä luvallisesti tuodun unen ja muun liikunnan yhteenvetoja. Paikalliset säännöt ja omat asetuksesi rajaavat muutoksia.</p><p>Jos verkko tai arvio ei ole saatavilla, harjoituksen kirjaaminen ja paikallinen analyysi eivät tarvitse uutta tekoälyvastausta. Vanha arvio ei ole reaaliaikainen mittaus tämänhetkisestä palautumisesta.</p>'),
  ('Viikkokysely ja automaattinen viikkopalaute', '<p><strong>Treeni-välilehden ⋮ → Viikkopalaute</strong> avaa kyselyn palautumisesta ja treeniviikon tuntemuksesta. Vastaa kokemuksesi mukaan ja tallenna; kyselyn voi myös ohittaa.</p><p>Valmentajan asetuksissa <strong>Viikkokysely</strong> ohjaa kyselyä ja <strong>Valmentajan viikkopalaute</strong> valmistuneen arvion automaattista näyttämistä. Ne ovat eri valintoja. Jos viikolta puuttuu treenejä, tarkista palautteessa näkyvä ajanjakso ja omat historiakirjaukset.</p>'),
  ('Ohjelman hienosäätö tulevia treenejä varten', '<p>Ohjelman hienosäätö voi ehdottaa pieniä sarjamäärän tai liikejärjestyksen muutoksia tulevaan ohjelmaan. Valitse <strong>Vain ehdotukset</strong>, <strong>Automaattinen</strong> tai <strong>Pois</strong> tämän toiminnon asetuksista.</p><p>Ehdotustilassa tarkista muutoslista ja hyväksy se tai valitse <strong>Ei nyt</strong>. Automaattinen tila voi ottaa tarkistetut muutokset käyttöön uuden kokonaisarvion jälkeen. Käynnissä oleva treeni ei muutu ohjelman hienosäädöstä.</p>'),
  ('Mitä arvio kertoo – ja mitä dataa tarvitaan?', '<p>Kirjaa toteutuneet sarjat, toistot, painot ja ajat oikein. Pidempi vertailukelpoinen historia auttaa erottamaan kehityssuunnan yksittäisestä poikkeamasta. Aloittelijasta tai tauolta palanneesta voi ensin kertyä lisää havaintoja.</p><p>Valmentaja ei näe tekniikkaasi eikä tunnista kipua tai vammaa. Uniyhteenveto on käytettävissä vain, jos olet ottanut tuonnin käyttöön ja dataa on saatavilla. Puuttuva tieto ei ole huono tulos.</p>')],
 [('12-valmentaja', 'Valitse toimintatapa ja säädä tarvittaessa toimintoja erikseen.')])

chapter('kehonhuolto', 'Kehonhuolto ja loppuvenyttely',
 'Loppuvenyttely täydentää tehtyä treeniä. Erillinen kehonhuolto sopii myös päivään, jolloin et tee voimaharjoitusta.',
 '<strong>Treenin ⋮ → Aloita loppuvenyttely</strong> · <strong>Kehonhuolto</strong>-välilehti',
 ['Loppuvenyttelyyn siirryt treenin valikosta. Kehonhuollossa valitse palauttava harjoitus tai liikkuvuus.', 'Valitse kehonhuollon painopiste ja sopiva kesto. Tarkista muodostettu liikesarja.', 'Käynnistä liikkeen ajastin ja etene kortista seuraavaan. Päätä harjoitus lopuksi valikosta.'],
 [('Treeniin sopiva loppuvenyttely', '<p>GymTracker kokoaa loppuvenyttelyä harjoituksen kuormittamien alueiden ja liikemallien perusteella. Jos työsarjoja puuttuu, sovellus pyytää vahvistamaan siirtymisen.</p><p>Liikekuvista näet etenemisen. Käynnistä ajastin, avaa liikkeen ohje tai ohita tarvittaessa liike. Jos harjoitusta muutetaan, tarjolla oleva päivitystoiminto voi muodostaa loppuvenyttelyn uudelleen.</p>'),
  ('Palauttava harjoitus ja liikkuvuus', '<p>Valitse <strong>Palauttava</strong>, kun haluat rauhallisia liikkeitä ja kevyitä venytyksiä. <strong>Liikkuvuus</strong> painottaa aktiivisia liikeratoja ja hallintaa.</p><p>Valitse koko keho, lonkat ja alavartalo tai ylävartalo ja selkä. Lajiasi tukeva painopiste tulee tarjolle ohjelmasi mukaan. Valitse 5, 10 tai 15 minuutin kokonaisuus saatavilla olevista vaihtoehdoista.</p>'),
  ('Ajastimet, puolet ja ohjeet', '<p>Yksi liike näkyy kerrallaan. Avaa suoritusohje ja lihaskartta tarvittaessa. Käynnistä ajanotto vasta, kun olet asennossa. Kaksipuolisessa liikkeessä tee molemmat puolet niiden omien ajastimien mukaan.</p><p>Siirry kuvarivistä, siirtymäpalkeista tai pyyhkäisemällä. Tarkista harjoituksen päättyessä tehdyt liikkeet. Valmis kehonhuolto tallentuu Historiaan.</p>'),
  ('Valinnainen taustamusiikki', '<p>Musiikkisoitin näkyy venyttelyn ja kehonhuollon alareunassa, kun toiminto on käytössä. Käytä toisto-, tauko- ja kappaleenvaihtopainikkeita tai sulje soitin.</p><p>Asetus löytyy kohdasta <strong>Asetukset → Sovelluksen asetukset → Näyttö ja äänet → Venyttelyn ja kehonhuollon taustamusiikki</strong>.</p>')],
 [('10-kehonhuolto', 'Valitse harjoituksen tyyppi, painopiste ja kesto.'), ('06-loppuvenyttely', 'Loppuvenyttelyssä liikkeillä on ohjeet ja omat ajastimet.')])

chapter('historia', 'Historia ja kehitys',
 'Historia kokoaa voimaharjoitukset, kehonhuollot ja muun liikunnan. Kehitystä kannattaa katsoa useamman harjoituksen kokonaisuutena.',
 '<strong>Historia → Yleiskatsaus</strong> tai <strong>Kehitys</strong>',
 ['Tarkista viikon aktiivisuus ja avaa haluamasi päivä kalenterista.', 'Avaa harjoitus nähdäksesi yhteenvedon, liikkeet ja sarjat.', 'Vaihda Kehitys-välilehteen, valitse ajanjakso ja tarkastele työmäärää tai voimatasoja.'],
 [('Kalenteri, tilastot ja yksittäisen harjoituksen tiedot', '<p>Yleiskatsaus näyttää tämän viikon, aktiivisuuskalenterin ja yhteenvedot. Avaa kalenteri, selaa kuukausia ja napauta päivää nähdäksesi sen harjoitukset. Viimeisimmät aktiivisuudet -listasta avaat saman sisällön suoraan.</p><p>Treenin yhteenvedossa näkyvät suoritusaste, kesto, tehdyt sarjat, lihaskuormitus ja saatavilla olevat syke- ja energiatiedot. Avaa treenin tiedot tarkistaaksesi liikkeet ja sarjat. Kehonhuollolla ja muulla liikunnalla on omat yhteenvetonsa.</p><p>Tilastojen tietopainikkeet selittävät laskentaa. Historiasta voi myös poistaa harjoituksen; vahvista vain, jos haluat poistaa sen tiedot.</p>'),
  ('Ajanjaksot, vertailu ja työmäärä', '<p>Kehitys-välilehdellä valitse <strong>4 vk, 3 kk, Vuosi tai Kaikki</strong>. Näet harjoitusten, harjoitusajan ja työsarjojen kertymää. Vertailu käyttää edeltävää samanpituista jaksoa silloin, kun vertailu on saatavilla.</p><p>Työmääräkuvaajat kertovat treenien ja tehtyjen työsarjojen määristä. Kohokohdista voit avata uudet ennätykset ja nousussa olevat liikkeet. Pieni tai puuttuva vertailuaineisto voi jättää näkymän vielä tyhjäksi.</p>'),
  ('Arvioitu 1RM ja kokonaiskehityksen voimaindeksi', '<p><strong>Arvioitu 1RM</strong> lasketaan painosta ja toistoista treenin parhaan tehdyn sarjan perusteella. Se on kehitysmittari, ei mitattu maksimisuoritus. Valitse liike tarkastellaksesi sen käyrää, viimeisintä arvoa, parasta tulosta ja muutosta.</p><p><strong>Kokonaiskehitys</strong> yhdistää vertailukelpoisten liikkeiden kehitystä voimaindeksiksi. Liikkeen lähtötaso on 100, ja kukin liike vaikuttaa kokonaisuuteen yhtä paljon. Ajanjakson vaihto rajaa näkyvää käyrää; se ei nollaa lähtötasoa.</p><p>Tietopainike <strong>Miten voimakehitys lasketaan</strong> kertoo lisää. Kaikista liikkeistä, kuten pelkästä ajanotosta, ei muodostu samanlaista paino–toisto-kehitystä.</p>'),
  ('Syke, energia ja muiden sovellusten harjoitukset', '<p>Syke ja energia -kooste näyttää saatavilla olevia kellosta tallennettuja tietoja valitulta ajalta. Avaa yksittäinen harjoitus nähdäksesi sen tarkemman sykekäyrän, jos näytteitä on.</p><p>Health Connect -tuonnit näkyvät Historiassa omalla lähteellään. Tuotu harjoitus kertoo muusta aktiivisuudesta, mutta se ei muutu GymTrackerin liike- ja sarjahistoriaksi.</p>')],
 [('08-historia', 'Yleiskatsaus kokoaa viikon ja viimeisimmän aktiivisuuden.'), ('09-kehitys', 'Kehitys-välilehdellä vaihdat ajanjaksoa ja vertaat kokonaisuuksia.')])

chapter('wear-os', 'Wear OS -kello',
 'Wear OS -kumppani vähentää tarvetta ottaa puhelin esiin jokaisen sarjan jälkeen. Laajemmat ohjelmamuutokset teet puhelimessa.',
 '<strong>Asetukset → Wear OS</strong>',
 ['Asenna GymTracker sekä Android-puhelimeen että yhteensopivaan Wear OS -kelloon ja pidä laitteet yhteydessä.', 'Ota kellotuki käyttöön puhelimen asetuksista. Anna kellossa tarvittavat liikunta- ja terveysluvat, jos haluat mittaukset.', 'Aloita tai jatka harjoitusta puhelimesta ja avaa GymTracker kellossa. Jos harjoitus ei näy, valitse Yritä uudelleen.'],
 [('Sarjat, painot, ajanotto ja synkronointi', '<p>Kellosta voit merkitä sarjoja, muuttaa toistoja ja painoja, käyttää aikapohjaisia sarjoja sekä siirtyä liikkeestä toiseen. Liikenäkymä ja kirjatut tiedot synkronoituvat puhelimen kanssa.</p><p>Lämmittely, lepoajastin ja loppuvenyttely näkyvät tuetuissa harjoituksissa. Voit aloittaa loppuvenyttelyn tai päättää treenin kellosta; tekemättömät sarjat voivat vaatia vahvistuksen. Valmentajan ehdotukset tarkistat ja hyväksyt puhelimessa.</p>'),
  ('Kehonhuolto ja kellosta aloitettava muu liikunta', '<p>Kello seuraa puhelimen aktiivista kehonhuoltoa ja loppuvenyttelyä. Käytä liikkeiden ajastimia ja puolten vaihtoa kellon näkymän ohjeiden mukaan.</p><p>Kellon aloitusnäkymän <strong>Muut treenit</strong> -valinnasta voi aloittaa tuetun muun lajin. Kellosovellus käyttää yhteyttä puhelimeen; pidä puhelin mukana ja varmista harjoituksen näkyminen molemmissa laitteissa.</p>'),
  ('Syke, kalorit ja askeleet', '<p>Yhteensopiva kello voi tallentaa sykettä, arvioituja aktiivisia kaloreita ja askelia. Laitetuki, anturit, luvat ja mittauksen onnistuminen määräävät, mitä tietoja syntyy.</p><p>Tiedot näkyvät saatavuuden mukaan harjoituksen mittareissa, yhteenvedossa ja Historiassa. Kaloriluku on arvio; tyhjä arvo ei tarkoita nollakulutusta.</p>'),
  ('Kellon ulkoasu, hereilläpito ja värinät', '<p>Puhelimen Wear OS -asetuksista säädät lepoajastimen näkyvyyttä, harjoitusnäkymän hereilläpitoa, lepo- ja aikasarjavärinöitä, tekstin kokoa ja käyttöliittymän kokoa.</p><p>Hereilläpito voi lisätä virrankulutusta. Jos näyttö himmenee, nosta rannetta tai napauta näyttöä. Kellotaululta pääset takaisin avaamalla GymTrackerin.</p>')],
 [('16-wear-asetukset', 'Kellon näkymää ja värinöitä säädetään puhelimen Wear OS -asetuksista.')])

chapter('health-connect', 'Health Connect',
 'Health Connect tuo muiden sovellusten harjoituksia ja unitietoja GymTrackeriin sekä välittää valmistuneita harjoituksia muihin sovelluksiin.',
 '<strong>Asetukset → Sovelluksen asetukset → Health Connect</strong>',
 ['Tarkista, että Health Connect on saatavilla laitteessasi.', 'Ota vienti ja tuonti käyttöön erikseen. Myönnä haluamiesi tietojen kirjoitus- tai lukuluvat.', 'Käytä Tuo nyt -painiketta tuonnin päivittämiseen. Valmiin treenin yhteenvedosta voit tarkistaa viennin tilan tai yrittää vientiä uudelleen.'],
 [('Valmistuneiden treenien vienti', '<p><strong>Vie treenit</strong> sallii valmistuneiden harjoitusten viennin. Kirjoitusluvat määräävät, voidaanko viedä harjoituksen lisäksi esimerkiksi sykenäytteitä, aktiivisia kaloreita, matkaa tai reittiä.</p><p>Pelkkä harjoituslupa voi riittää perustietoihin. Muut tiedot vaativat omat oikeutensa ja saatavilla olevan datan. Vastaanottava sovellus päättää, mitä Health Connectin tiedoista se osaa näyttää.</p>'),
  ('Muun liikunnan ja unen tuonti', '<p><strong>Tuo terveystietoja</strong> tuo muiden sovellusten harjoitukset ja unisessiot viimeiseltä neljältä viikolta. Tuonti tarvitsee omat lukulupansa.</p><p>Tiedot päivittyvät sovellusta avatessa ja <strong>Tuo nyt</strong> -painikkeella. <strong>Salli päivitys taustalla</strong> mahdollistaa päivityksen taustalla laitteen tuen ja lupien rajoissa. Harjoitukset näkyvät Historiassa lähdetietoineen.</p><p>Unen ja muun aktiivisuuden yhteenvetoja voidaan käyttää Valmentajan tekoälyarviossa. Jos tietoa ei ole, sitä ei tulkita huonoksi palautumiseksi.</p>'),
  ('Luvat, reitit ja ongelmatilanteet', '<p>Vienti- ja tuontiluvat ovat erilliset. Hallitse ja peru niitä Androidin Health Connect -asetuksissa. GPS-tallennus ei yksin anna muille sovelluksille oikeutta reittiin.</p><p>Jos tietoja puuttuu, tarkista Health Connectin luvat, GymTrackerin kytkimet ja lähdesovelluksen tallennukset. Reitti voi vaatia erillisen luvan tai hyväksynnän. Vain valmistunut harjoitus voidaan viedä.</p>')],
 [('17-health-connect', 'Ota tietojen vienti ja tuonti käyttöön omilla valinnoillaan.')])

chapter('asetukset', 'Asetukset',
 'Muutama harkittu asetus riittää. Voit säätää harjoittelun perustietoja, näkymää ja muistutuksia myöhemminkin.',
 '<strong>⋮ → Asetukset</strong>',
 [],
 [('Kokemus, perustiedot ja käytettävät välineet', '<p><strong>Treenaaminen → Treeniasetukset</strong> sisältää vapaaehtoiset perustiedot, kokemustason, välineet, treenipäivät ja liikkeet. Päivitä kokemustasosi, kun harjoitustaustasi muuttuu olennaisesti.</p><p>Tarkista välineet erikseen salille ja koti-/ulkotreeneihin. Omat valinnat auttavat ohjelmanluontia ja liikevaihtoja löytämään toteuttamiskelpoisia vaihtoehtoja.</p>'),
  ('Näyttö ja äänet', '<p>Avaa <strong>Sovelluksen asetukset → Näyttö ja äänet</strong>. Valitse harjoitusnäkymän hereilläpito ja venyttelyn sekä kehonhuollon taustamusiikki.</p><p>Hereillä oleva näyttö helpottaa käyttöä, mutta kuluttaa akkua. Kellon näyttöasetukset ovat erikseen kohdassa <strong>Wear OS</strong>.</p>'),
  ('Treenirytmimuistutukset ja taukoviestit', '<p>Avaa <strong>Sovelluksen asetukset → Muistutukset</strong>. Voit sallia treenirytmiin perustuvat muistutukset ja pidempään taukoon liittyvät viestit erikseen. Valitse myös muistutusten kellonaika.</p><p>Muistutus tarvitsee Androidin ilmoitusluvan. Jos muistutukset on hiljennetty, asetuksissa näkyy mahdollisuus poistaa hiljennys. Kaikki päivät eivät tuota ilmoitusta: muistutus lähetetään, kun sille löytyy syy.</p>'),
  ('Käyttöanalytiikka, tiedot ja yhteystiedot', '<p><strong>Sovelluksen asetukset → Käyttöanalytiikka</strong> antaa valita perustason käyttötietojen jakamisen. Analytiikkavalinta on erillinen Valmentajan tekoälyarviosta ja Health Connectin oikeuksista.</p><p><strong>⋮ → Tietoja sovelluksesta</strong> näyttää version, kehittäjän, yhteystiedot, verkkosivun ja tietosuojalinkit. Sieltä pääset myös Google Playn sovellussivulle. Turvallisuusohjeet löytyvät Asetuksista.</p>')])

chapter('varmuuskopiointi', 'Varmuuskopiointi',
 'Varmuuskopio auttaa puhelimen vaihtuessa ja vahinkojen varalta. Tallenna kopio paikkaan, johon pääset myös toiselta laitteelta.',
 '<strong>Asetukset → Sovelluksen asetukset → Varmuuskopiointi</strong>',
 ['Valitse Vie varmuuskopio ja tallennuspaikka Androidin tiedostovalitsimessa.', 'Tarkista, että sovellus vahvistaa tiedoston tallentumisen.', 'Uudella laitteella valitse Tuo varmuuskopio ja avaa tallennettu GymTracker-tiedosto. Lue palautuksen vahvistus.'],
 [('Manuaalinen vienti ja palautus', '<p>Vie kopio ennen puhelimen vaihtoa tai sovelluksen tietojen poistamista. Voit käyttää laitteen tallennustilaa tai tiedostovalitsimessa näkyvää pilvipalvelua, kuten Google Drivea.</p><p>Tuonti palauttaa tiedoston sisältämää harjoitusdataa. Se ei ole sama asia kuin kahden puhelimen jatkuva synkronointi. Säilytä ennen tuontia myös nykyisistä tiedoistasi kopio, jos haluat varmistaa niiden säilymisen.</p>'),
  ('Automaattinen varmuuskopiointi', '<p>Valitse varmuuskopiotiedosto ja ota automaattinen varmuuskopiointi käyttöön, kun käyttöoikeutesi sallii sen. Valitse aikaväliksi treenin jälkeen, viikoittain, kahden viikon välein tai kuukausittain.</p><p>Automaattinen varmuuskopiointi pitää <strong>yhden valitsemasi tiedoston</strong> ajan tasalla. Tarkista asetuksista viimeisin onnistunut varmuuskopio. Jos siirrät tiedoston tai pilvipalvelun käyttöoikeus muuttuu, valitse tallennuspaikka uudelleen.</p>'),
  ('Puhelimen vaihto ja tietojen yksityisyys', '<p>Harjoitusdata tallennetaan ensisijaisesti laitteelle. Omat varmuuskopiot menevät valitsemaasi paikkaan. Tekoälyarvioita varten tarvittavia yhteenvetoja käsitellään palvelinyhteyden kautta, ja Health Connect -siirrot noudattavat omia lupiaan.</p><p>Varmuuskopio voi sisältää henkilökohtaisia harjoitustietoja: säilytä se omassa luotetussa tallennustilassasi. Palauta tilaus erikseen Google Playn ostojen palautuksella.</p><p>Aiemman asennuksen maksuton erityisoikeus ei välttämättä siirry uuteen asennukseen tai uuteen puhelimeen. Tarkista oma tilausnäkymä ennen sovelluksen poistamista tai tietojen tyhjentämistä.</p>')],
 [('18-varmuuskopiointi', 'Valitse automaattiselle kopiolle tiedosto ja tarkista viimeisin onnistunut tallennus.')])

chapter('pulmat', 'Ongelmatilanteet',
 'Aloita näistä nopeista tarkistuksista. Oman versionumeron löydät kohdasta ⋮ → Tietoja sovelluksesta.',
 '', [],
 [('En löydä toimintoa tai näkymä näyttää erilaiselta', '<p>Avaa oikean näkymän <strong>⋮</strong>-valikko: sen toiminnot vaihtuvat tilanteen mukaan. Tarkista käyttöoikeus, sovellusversio ja tarvittavat laiteluvat. Kaikilla laitteilla ei ole samoja mittareita.</p><p>Tämä ohje kuvaa version 2.3.1.5 näkymiä ja niitä vastaavaa toteutusta. Käyttöliittymä ja käyttöoikeuksien nimet voivat muuttua päivityksissä.</p>'),
  ('Kello ei näytä treeniä tai syke puuttuu', '<p>Varmista asennus molemmissa laitteissa, niiden yhteys ja puhelimen Wear OS -asetus. Avaa sovellus puhelimessa ja kellossa, jatka aktiivista treeniä ja valitse kellosta <strong>Yritä uudelleen</strong>.</p><p>Syke tarvitsee tuetun kellon, asianmukaiset luvat ja onnistuneen mittauksen. Tarkista kellon anturin kosketus ja luvat. Pelkkä toimiva sarjasynkronointi ei vielä takaa terveystietojen saatavuutta.</p>'),
  ('GPS tai Health Connect ei tuo tietoja', '<p>GPS-reitti tarvitsee sijaintiluvan ja GPS:n käyttöönoton ennen tallennusta. Tarkista myös puhelimen sijaintiasetukset. GPS-katkos näkyy ilmoituksena harjoituksessa.</p><p>Health Connectin tuonti ja vienti tarvitsevat omat lupansa. Tarkista ensin lähdesovelluksen tiedot ja käytä sitten GymTrackerin <strong>Tuo nyt</strong> -painiketta tai harjoituksen viennin uudelleenyritystä.</p>'),
  ('Valmentajan arvio puuttuu tai ehdotuksia ei tule', '<p>Tarkista Valmentajan pääkytkin ja kyseisen toiminnon tila. Arvio tarvitsee riittävästi soveltuvaa dataa ja tekoälyarvio verkkoyhteyden. Uutta muutosta ei tarvita jokaiseen harjoitukseen.</p><p>Tarkista palautteen ajanjakso ja päivitysaika. Historiassa näkyvä tämän viikon treeni ei automaattisesti kuulu edellisen viikon palautteeseen. Yritä arvion päivitystä myöhemmin, jos palvelu ei vastaa.</p>'),
  ('Tilaus tai varmuuskopion palautus ei näy oikein', '<p>Tarkista ostossa käytetty Google-tili, verkkoyhteys ja <strong>Palauta ostot</strong>. Vahvistusta odottava Google Play -maksu ei vielä tarkoita aktiivista tilausta. Käyttöoikeuden tarkistusvirhe ei itsessään poista harjoitushistoriaa.</p><p>Varmista, että valitsit oikean GymTracker-varmuuskopion ja että tiedosto on käytettävissä. Jos tallennuspaikka on pilvipalvelussa, tarkista sen yhteys ja tiedostolupa.</p>'),
  ('Tarvitsen apua tai haluan ilmoittaa virheestä', '<p>Lähetä kuvaus osoitteeseen <a href="mailto:gymtracker@donturexdev.fi">gymtracker@donturexdev.fi</a>. Kerro puhelin- ja kellomalli, Android-/Wear OS -versio, GymTracker-versio ja lyhyet toistovaiheet.</p><p>Kerro, mitä odotit ja mitä tapahtui. Kuvankaappaus auttaa; tarkista ennen lähettämistä, ettei siinä näy henkilökohtaisia tietoja, joita et halua jakaa.</p>')])

def shot_html(name, caption):
    return f'''<figure class="shot"><button type="button" class="shot-button" aria-label="Suurenna kuva: {escape(caption, quote=True)}"><span class="phone"><img src="assets/{name}.webp" width="720" height="1616" loading="lazy" decoding="async" alt="{escape(caption, quote=True)}"></span></button><figcaption><span class="caption-text">{escape(caption)}</span> <span class="zoom-hint">Napauta suuremmaksi.</span></figcaption></figure>'''

nav = ''.join(f'<a data-chapter-link href="#{c["slug"]}"><span>{i:02}</span> {escape(c["title"])}</a>' for i,c in enumerate(chapters,1))
context_shots = {'treeni-2': '04-painon-syotto', 'kehonhuolto-1': '06-loppuvenyttely', 'historia-2': '09-kehitys'}
sections = []
for i, c in enumerate(chapters,1):
    steps = '<ol class="steps">' + ''.join(f'<li>{s}</li>' for s in c['steps']) + '</ol>' if c['steps'] else ''
    features = []
    for j, (title, body) in enumerate(c['features'], 1):
        feature_id = f'{c["slug"]}-{j}'
        related = ''.join(shot_html(*s) for s in c['shots'] if s[0] == context_shots.get(feature_id))
        features.append(f'<details class="feature" id="{feature_id}"><summary>{title}</summary><div class="feature-body">{body}{related}</div></details>')
    features = ''.join(features)
    primary = [s for s in c['shots'] if s[0] not in context_shots.values()]
    shots = '<div class="screenshots">' + ''.join(shot_html(*s) for s in primary) + '</div>' if primary else ''
    path = f'<p class="path">{c["path"]}</p>' if c['path'] else ''
    grid = 'chapter-grid' if c['shots'] else 'chapter-content'
    sections.append(f'''<section class="chapter" id="{c['slug']}" aria-labelledby="heading-{c['slug']}"><div class="chapter-head"><span class="chapter-number">{i:02}</span><h2 id="heading-{c['slug']}">{c['title']}</h2></div><p class="chapter-intro">{c['intro']}</p><div class="{grid}"><div class="chapter-content">{path}{steps}{features}</div>{shots}</div></section>''')

